[
  {
    "title": "pre-fight-help-not-visible",
    "claim": "The qualifier card in Image #2 shows FIGHT and both sticks, but neither the Techniques nor Settings control visible in Image #3.",
    "reason": "A new player needs access to instructions and accessibility options before starting the fight.",
    "suggest": "Expose the existing Techniques and Settings actions on the qualifier card alongside FIGHT."
  },
  {
    "title": "stick-actions-separated-from-controls",
    "claim": "In Image #3, the stick rims contain only directional chevrons, while their action mappings appear in a separate strip above them.",
    "reason": "The player must translate between the legend and the thumb position rather than read the action at its input location.",
    "suggest": "Replace the rim chevrons with the corresponding action labels, preserving the centered stick position and an 18 CSS px text minimum."
  },
  {
    "title": "desktop-key-legend-absent",
    "claim": "Image #9 shows STANCE and TECHNIQUE beneath the desktop sticks without any visible keyboard key mappings.",
    "reason": "The displayed controls do not tell a keyboard player which keys to use.",
    "suggest": "Show the actual configured stance and technique keys in the unused space between the desktop sticks."
  },
  {
    "title": "briefing-copy-all-caps",
    "claim": "Image #2 renders both the opponent briefing and the multi-line move instruction in widely spaced uppercase text.",
    "reason": "The explanatory copy competes with the round heading instead of providing an easily scanned introduction.",
    "suggest": "Keep the heading uppercase, but render the briefing and instructions in sentence case with left alignment and normal letter spacing."
  },
  {
    "title": "kick-silhouette-unresolved",
    "claim": "Images #13 and #22 both display FRONT KICK, but the lifted foot is not clearly separable in #13 as it is in #22; this difference alone does not establish sprite clipping.",
    "reason": "A readable attack silhouette matters, but a normal pose or foreshortened limb must not be mistaken for missing artwork.",
    "suggest": "Make no sprite correction yet; capture the exact pose identifier and atlas rectangle for #13, then compare the rendered silhouette with the source cell's alpha bounds and consecutive frames."
  }
]
